SET @prov_c := '%s';
SET @id:= '%s';
SET @cat_id := '%s';
SET @send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);
SET @b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET	@start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

 CREATE TABLE IF NOT EXISTS s_rdu16(
  id varchar(32) NOT NULL,
  hospcode varchar(5) NOT NULL,
  areacode varchar(8) NOT NULL,
  flag_sent varchar(1) DEFAULT NULL,
  date_com varchar(14) DEFAULT NULL,
  b_year varchar(4) NOT NULL,
	target int(9) DEFAULT 0,
	result int(9) DEFAULT 0,
	PRIMARY KEY (id,hospcode,areacode,b_year),
	KEY (hospcode),
	KEY (areacode),
	KEY (b_year)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DELETE FROM s_rdu16 WHERE id=@id AND b_year=(@b_year+543);

DROP TEMPORARY TABLE IF  EXISTS  t_ht_rdu ;
CREATE TEMPORARY TABLE IF NOT EXISTS  t_ht_rdu AS
SELECT
o.HOSPCODE,o.PID
,TIMESTAMPDIFF(year,p.birth,o.date_serv) age_y
,o.SEQ,o.DATE_SERV
,GROUP_CONCAT(o.DIAGCODE ORDER BY o.diagtype) DIAGCODE
,GROUP_CONCAT(o.DIAGTYPE ORDER BY o.diagtype) DIAGTYPE
,d.DIDSTD,d.DNAME ,d.AMOUNT
,COUNT(DISTINCT  CONCAT(o.HOSPCODE,o.PID)) tcount
,COUNT(DISTINCT  CONCAT(d.HOSPCODE,d.PID)) rcount
FROM  tmp_diag_opd o
INNER JOIN chospital h ON o.hospcode=h.hoscode AND h.hostype IN(5,6,7,11,15)
INNER JOIN t_person_db p ON o.HOSPCODE=p.HOSPCODE AND o.PID=p.PID
LEFT JOIN tmp_drug_asu d ON o.hospcode=d.HOSPCODE AND o.PID=d.PID AND o.SEQ=d.SEQ 
		AND o.DATE_SERV=d.DATE_SERV AND CHK_GER = 'Y'  AND d.amount > 0 AND d.scount=1
WHERE  TIMESTAMPDIFF(year,p.birth,o.date_serv) >=65	AND o.date_serv BETWEEN @start_d AND @end_d 
GROUP BY o.HOSPCODE,o.PID,o.SEQ,o.DATE_SERV;

INSERT IGNORE INTO s_rdu16
(
SELECT
@id,d.hospcode,concat(h.provcode,SUBSTR(CONCAT('00',h.distcode),-2),SUBSTR(CONCAT('00',h.subdistcode),-2),SUBSTR(CONCAT('00',h.mu),-2)) as areacode
,@send,DATE_FORMAT(now(),'%Y%m%d%H%i%s') as d_com,@b_year+543 as b_year
,COUNT(DISTINCT IF(d.tcount IN(1), CONCAT(d.hospcode,'-',d.pid,'-',d.seq),NULL)) target
,COUNT(DISTINCT IF(d.rcount IN(1), CONCAT(d.hospcode,'-',d.pid,'-',d.seq),NULL)) result
FROM t_ht_rdu d INNER JOIN chospital h ON d.hospcode=h.hoscode
GROUP BY hoscode
);
